export type DeleteOrganizationInput = z.infer<typeof deleteOrganizationSchema>;
export type TransferOwnershipInput = z.infer<typeof transferOwnershipSchema>;

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}

/**
 * Collects one recipient's unread notifications inside the window. Returns
 * `null` — rather than an empty bundle — when the org's plan does not include
 * the digest, or when there is nothing to say: the caller treats `null` as
 * "send nothing", so a quiet day produces no mail at all.
 */
export async function buildDigest(
  orgId: OrgId,
  recipientId: UserId,
  windowStart: IsoTimestamp,
  windowEnd: IsoTimestamp,
): Promise<DigestBundle | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;

  const unread = await notificationRepo.listUnreadSince(
    orgId,
    recipientId,
    windowStart,
  );

  const entries: DigestEntry[] = unread
    .filter((notification) => notification.createdAt <= windowEnd)
    .map((notification) => ({
      notificationId: notification.id,
      kind: notification.kind,
      title: notification.title,
      href: notification.href,
      occurredAt: notification.createdAt,
    }))
    .slice(0, DIGEST_MAX_ENTRIES);

  if (entries.length < MIN_ENTRIES) return null;

  return { orgId, recipientId, entries, windowStart, windowEnd };
}

/**
 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`. Opting into the digest is what suppresses the immediate
 * emails, so the two lists are two views of the same preference.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  return preferenceRepo.listDigestSubscribers(orgId);
}

/** Renders one bundle through the shared email pipeline. */
export async function renderDigest(
  bundle: DigestBundle,
  recipient: User,
): Promise<RenderedEmail> {
  return renderEmail("digest", {
    orgId: bundle.orgId,
    recipientName: recipient.name,
    entryCount: bundle.entries.length,
    windowStart: bundle.windowStart,
    windowEnd: bundle.windowEnd,
    headline: bundle.entries[0]?.title ?? "",
  });
}
/**
 * Session rows for the cookie-based auth: create, look up by token hash, revoke.
 */
import { eq, lt } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, sessions, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp } from "./_mappers";
import type {
  IsoTimestamp,
  OrgId,
  SessionId,
  UserId,
} from "@/types/common";
import type { SessionPrincipal } from "@/types/member";

/**
 * Sessions are global rather than tenant-scoped: one cookie can move between
 * organizations via `activeOrgId`, and `SessionService` resolves the `Actor`
 * for whichever org the request addresses.
 */
export async function createSession(
  userId: UserId,
  tokenHash: string,
  expiresAt: IsoTimestamp,
): Promise<SessionPrincipal> {
  const stamp = toIsoTimestamp(new Date());
  const user = getDb().select().from(users).where(eq(users.id, userId)).get();
  if (!user) throw new Error(`User ${userId} not found`);

  getDb()
    .insert(sessions)
    .values({
      id: newId(),
      userId,
      activeOrgId: null,
      tokenHash,
      expiresAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();

  return {
    userId,
    email: user.email,
    activeOrgId: null,
    expiresAt,
  };
}

/** Expired rows resolve to `null` rather than being returned and re-checked. */
export async function findSessionByTokenHash(
  tokenHash: string,
): Promise<SessionPrincipal | null> {
  const row = getDb()
    .select({ session: sessions, user: users })
    .from(sessions)
    .innerJoin(users, eq(users.id, sessions.userId))
    .where(eq(sessions.tokenHash, tokenHash))
    .get();

  if (!row) return null;
  if (row.session.expiresAt <= new Date().toISOString()) return null;

  return {
    userId: brandId<UserId>(row.session.userId),
    email: row.user.email,
    activeOrgId:
      row.session.activeOrgId === null
        ? null
        : brandId<OrgId>(row.session.activeOrgId),
    expiresAt: brandStamp(row.session.expiresAt),
  };
}

export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

export async function revokeSession(sessionId: SessionId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Housekeeping sweep; returns how many rows the scheduler removed. */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}
